import os
from dotenv import load_dotenv

load_dotenv()

# --- Telegram ---
TELEGRAM_BOT_TOKEN = os.getenv("TELEGRAM_BOT_TOKEN", "")
TELEGRAM_CHAT_ID = os.getenv("TELEGRAM_CHAT_ID", "")

# --- Sync behaviour ---
DATA_DIR = os.getenv("DATA_DIR", "data")

MIN_DISCOUNT_PERCENT = float(os.getenv("MIN_DISCOUNT_PERCENT", "80"))

# How often the scheduler re-syncs + re-checks prices. NOTE: this no
# longer drives the scheduler's loop timing directly (see
# CYCLE_DELAY_SECONDS below) — kept around because it's still reported by
# the /health endpoint and startup log for visibility.
CHECK_INTERVAL_MINUTES = int(os.getenv("CHECK_INTERVAL_MINUTES", "10"))

# Pause (in seconds) between one cycle finishing and the next one
# starting. Default 0 = no wait at all: as soon as a batch of URLs is
# scraped, synced to the DB, and notified on Telegram, the next batch
# starts immediately. Set this to a positive number (e.g. "30") if you
# ever want to throttle requests to Flipkart/Amazon again.
CYCLE_DELAY_SECONDS = float(os.getenv("CYCLE_DELAY_SECONDS", "0"))

# How many Flipkart URLs to process per cycle. Instead of scraping every
# URL in FLIPKART_URLS at once, the scheduler walks through them in
# fixed-size batches (round-robin), wrapping back to the first URL after
# the last one is processed. Set to a number >= len(FLIPKART_URLS) to
# restore the old "scan everything every cycle" behaviour.
FLIPKART_BATCH_SIZE = int(os.getenv("FLIPKART_BATCH_SIZE", "10"))

# Where the scheduler remembers which URL to resume from between cycles
# (and across restarts, since the process is meant to run forever anyway).
FLIPKART_BATCH_STATE_FILE = os.getenv(
    "FLIPKART_BATCH_STATE_FILE", os.path.join(DATA_DIR, "flipkart_batch_state.json")
)

# Same batching behaviour as Flipkart above, applied to AMAZON_URLS.
AMAZON_BATCH_SIZE = int(os.getenv("AMAZON_BATCH_SIZE", "10"))
AMAZON_BATCH_STATE_FILE = os.getenv(
    "AMAZON_BATCH_STATE_FILE", os.path.join(DATA_DIR, "amazon_batch_state.json")
)

URLS_FILE = os.getenv("URLS_FILE", "urls.txt")

# If true, the scheduler re-scrapes every cycle (Flipkart/Amazon URLs
# below, plus URLS_FILE if set) before syncing DATA_DIR. Set to "false"
# to only sync whatever JSON files already exist in DATA_DIR.
AUTO_SCRAPE = os.getenv("AUTO_SCRAPE", "true").lower() == "true"

